import type { Metadata } from "next";

export const SITE_URL = "https://www.n-muhammad.uz";
export const SITE_NAME = "Mukhammad Numonkhujaev";
// Generated by app/opengraph-image.tsx
const OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: SITE_NAME };

export const SITE_DESCRIPTION =
	"Mukhammad Numonkhujaev — software engineering student at Kookmin University (GKS scholar) building full-stack products with Next.js, NestJS and GraphQL.";

// Per-page metadata: canonical URL, og:url and twitter card all point at the page itself.
export function pageMetadata({
	title,
	description,
	path,
	image,
	article,
}: {
	title: string;
	description: string;
	path: string;
	/** Berilmasa umumiy OG rasm (app/opengraph-image.tsx) */
	image?: string;
	article?: { publishedTime: string; modifiedTime: string; tags: string[] };
}): Metadata {
	const ogImage = image ? { url: image, alt: title } : OG_IMAGE;
	return {
		title,
		description,
		alternates: { canonical: path },
		openGraph: {
			title,
			description,
			url: path,
			siteName: SITE_NAME,
			locale: "en_US",
			images: [ogImage],
			...(article
				? { type: "article", publishedTime: article.publishedTime, modifiedTime: article.modifiedTime, tags: article.tags }
				: { type: "website" }),
		},
		twitter: {
			card: "summary_large_image",
			title,
			description,
			images: [ogImage.url],
		},
	};
}
